const LV_KEY=LSKEY+'-lv';
const LVM=(()=>{try{return JSON.parse(localStorage.getItem(LV_KEY)||'{}')||{};}catch(e){return{};}})();
const LV_DEF={loc:'stack',hab:'grid',item:'grid',acc:'card',own:'stack',asset:'list',log:'list',pubcat:'card',pubgene:'grid',pubhab:'ticket',pubitem:'card',pubacc:'card'};
const LV_NAMES={card:'圖鑑',grid:'格狀',list:'清單',stack:'堆疊',tree:'族譜'};
const LV_TIP={card:'圖鑑卡片，點開看詳細內容',grid:'縮圖卡片多欄並排，點開看詳細內容',list:'一行一個、附縮圖',stack:'只顯示標題列，點開才看內容',tree:'依母本與配偶排列的族譜'};
const LVQ={},LVF={};
function lvMode(k){return LVM[k]||LV_DEF[k]||'list';}
function lvSet(k,v){LVM[k]=v;try{localStorage.setItem(LV_KEY,JSON.stringify(LVM));}catch(e){}}
const lvF=(k,f)=>(LVF[k]&&LVF[k][f])||'';
const lvOn=k=>!!((LVQ[k]||'').trim()||Object.values(LVF[k]||{}).some(Boolean));
const lvHit=(k,parts)=>{const q=(LVQ[k]||'').trim().toLowerCase();return !q||parts.filter(v=>v!=null).join(' ').toLowerCase().includes(q);};
function lvReset(k){delete LVQ[k];delete LVF[k];}
function lvRe(k){if(k.startsWith('pub'))renderPublic();else if(R_[UI.tab])R_[UI.tab]();}
function lvInput(){var f=ghRestGet("lvInput");return new.target?Reflect.construct(f,arguments):f.apply(this,arguments);}lvInput.__rs=1;
function listBar(k,o){const modes=o.modes||['stack','list','grid'];const m=lvMode(k);
 return`<div class="lvbar" data-lvbar="${k}">${o.noq?'':`<label class="f lvq">${H(o.label||'搜尋')}<input type="search" id="lq-${k}" data-lq="${k}" value="${H(LVQ[k]||'')}" placeholder="${H(o.ph||'輸入關鍵字')}" title="${H(o.tip||'輸入關鍵字即時篩選，不分大小寫')}"></label>`}
 ${(o.filters||[]).map(([fk,lab,opts])=>`<label class="f">${H(lab)}<select data-lf="${k}|${fk}" title="只顯示符合的項目"><option value="">全部</option>${opts.map(([v,n])=>`<option value="${H(v)}"${lvF(k,fk)===String(v)?' selected':''}>${H(n)}</option>`).join('')}</select></label>`).join('')}
 ${o.sort?sortSel(k):''}<span class="tiny muted lvcount">顯示 ${o.shown}／共 ${o.total}</span>${lvOn(k)?`<button class="g mini" data-act="lclear" data-k="${k}">清除篩選</button>`:''}${o.collapse?`<button class="g mini" data-act="lcollapse" data-k="${k}" title="把展開的項目全部收起">全部收合</button>`:''}
 <span style="flex:1"></span>${modes.length<2?'':`<div class="seg" role="group" aria-label="檢視方式">${modes.map(v=>`<button data-act="lview" data-k="${k}" data-v="${v}" aria-pressed="${m===v}" title="${H(LV_TIP[v])}">${LV_NAMES[v]}</button>`).join('')}</div>`}${viewsBar(k)}</div>${o.shown||!o.total?'':`<p class="tiny muted lvnone">沒有符合條件的項目。</p>`}`;}
/* 堆疊模式時把一個項目包成可收合的標題列 */
