  let n=0;(r&&r.alleles||[]).forEach(x=>{const a=IDX.al[x.sym]&&IDX.al[x.sym][x.s];if(a&&x.col!=null){const c=parseCol(x.col);a.col=Object.entries(c).map(([k,v])=>`${k}=${v}`).join('; ');n++;}});
