  const base=list;const uniqV=(a)=>[...new Set(a.filter(Boolean))];const tiers=[];base.forEach(x=>{if(x.tier&&!tiers.some(t=>t[0]===x.tier.c))tiers.push([x.tier.c,`${x.tier.c} ${x.tier.zh}`]);});
