function idbOpen(){return new Promise(res=>{try{if(typeof indexedDB==='undefined')return res(null);const r=indexedDB.open('algarance-genelab',1);r.onupgradeneeded=()=>{try{r.result.createObjectStore('kv');}catch(e){}};r.onsuccess=()=>res(r.result);r.onerror=()=>res(null);r.onblocked=()=>res(null);}catch(e){res(null);}});}
