function lookLayerCanvas(l,im,pal,sc){const w=Math.max(1,Math.round(l.w*sc)),h=Math.max(1,Math.round(l.h*sc));const c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');x.drawImage(im,0,0,w,h);
 const col=LOOK_COLROLES.has(l.role)&&pal&&isHex(pal[l.pk])?pal[l.pk]:null;
 if(col&&l.role==='fill'){x.globalCompositeOperation='source-in';x.fillStyle=col;x.fillRect(0,0,w,h);}
 else if(col&&(l.role==='tint'||l.role==='hue')){x.globalCompositeOperation=l.role==='tint'?'multiply':'color';x.fillStyle=col;x.fillRect(0,0,w,h);x.globalCompositeOperation='destination-in';x.drawImage(im,0,0,w,h);}
 x.globalCompositeOperation='source-over';return c;}
const lookOp=l=>l.role==='shade'?'multiply':l.role==='light'?'screen':(LOOK_BLENDS[l.blend]||'source-over');
