function lookChange(t){const d=t.dataset||{};
 if(d.psd){const f=t.files&&t.files[0];const v=d.psd;t.value='';if(f)psdImport(f,v==='new'?null:v);return true;}
 if(d.limp){const [i,f,j]=d.limp.split('|');const P=LOOK_PEND;if(!P)return true;if(f==='learn'){P.learn=t.checked;return true;}const r=P.rows[+i];if(!r)return true;if(f==='pt')r.pt=t.value;else if(f==='role'){r.role=t.value;if(LOOK_COLROLES.has(r.role)&&!r.pk)r.pk=(palSlots()[0]||{}).k||'';}else if(f==='pk')r.pk=t.value;else if(f==='rg'){const e=(r.legend||[])[+j];if(e)e.pk=t.value;}lookPendRender();return true;}
 if(d.lyr){const [pi,li,f]=d.lyr.split('|');const p=looksCfg().poses[+pi];const l=p&&p.layers[+li];if(!l)return true;
  if(f==='n'){l.n=t.value.trim()||l.on||'圖層';lookEd(l,'n');save();return true;}
  if(f==='pt'){l.pt=t.value;lookEd(l,'pt');}else if(f==='vis'){l.hid=!t.checked;lookEd(l,'hid');}
  else if(f==='role'){l.role=t.value;if(LOOK_COLROLES.has(l.role)&&!l.pk)l.pk=(palSlots()[0]||{}).k||'';lookEd(l,'role');lookEd(l,'pk');}
  else if(f==='pk'){l.pk=t.value;lookEd(l,'pk');}else if(f==='g'){l.g=t.value.trim();lookEd(l,'g');}
  save();if(f==='vis'||f==='pk')lookPreviewSoon();else renderSpecies();return true;}
 if(d.lpart){const [i,f]=d.lpart.split('|');const L=looksCfg();const x=L.parts[+i];if(!x)return true;const v=t.value.trim();
  if(f==='n'){if(!v||L.parts.some(y=>y!==x&&lookNorm(y.n)===lookNorm(v))){toast(v?'已有同名的部位':'名稱不能空白');t.value=x.n;return true;}if(x.n!==v){x.al=(x.al||[]).filter(a=>lookNorm(a)!==lookNorm(v));if(!x.al.some(a=>lookNorm(a)===lookNorm(x.n)))x.al.push(x.n);x.n=v;}}
  else if(f==='key'){const k=v.replace(/[^A-Za-z0-9_]/g,'');if(!k||L.parts.some(y=>y!==x&&y.key===k)){toast('內部'+TERMS.code+'只能用英數字與底線，且不能重複');t.value=x.key;return true;}x.key=k;}
  else if(f==='al'){x.al=[...new Set(v.split(/[、,，;；]/).map(s=>s.trim()).filter(Boolean))];}
  save();renderSpecies();return true;}
 if(d.lsel){UI.look=UI.look||{};const se=new Set(UI.look.sel||[]);t.checked?se.add(d.lsel):se.delete(d.lsel);UI.look.sel=[...se];renderSpecies();return true;}
 if(d.lpord){const p=lookPose((UI.look||{}).pose);if(!p)return true;if(t.checked)p.order=looksCfg().parts.map(x=>x.id);else delete p.order;save();renderSpecies();return true;}
 if(d.lpose){const p=lookPose((UI.look||{}).pose);if(!p)return true;p[d.lpose]=t.value.trim()||(d.lpose==='name'?'未命名姿勢':'');save();renderSpecies();return true;}
 if(d.lvar){const p=lookPose((UI.look||{}).pose);if(!p)return true;p.vars=(p.vars||[]).filter(x=>x!==d.lvar);if(t.checked)p.vars.push(d.lvar);save();return true;}
 if(d.ldef){const p=lookPose((UI.look||{}).pose);if(!p)return true;const L=looksCfg();if(t.checked)L.def[d.ldef]=p.id;else if(L.def[d.ldef]===p.id)delete L.def[d.ldef];save();renderSpecies();return true;}
 if(d.look){UI.look=UI.look||{};UI.look[d.look]=t.type==='checkbox'?t.checked:t.value;lookPreviewSoon();return true;}
 if(d.indpose){const ind=S.inds[+d.indpose];if(!ind)return true;if(t.value)ind.pose=t.value;else delete ind.pose;UI.open=ind.id;save();renderReg();return true;}
 return false;}
