const LOOK_SOFT_NAME=/^(?:從選取範圍|由選取範圍|插入的圖像|圖層|图层|layer|layer via (?:copy|cut)|群組|群组|組|组|group|形狀|形状|shape)(?:\s*\d+)?(?:\s*(?:拷貝|拷贝|copy)(?:\s*\d+)?)?$/i;
function lookSoftName(nm){return LOOK_SOFT_NAME.test(String(nm||'').trim());}
/* ================= 第 38 版：AI 指示框（每個 AI 按鈕的 ▾）、新的 AI 功能（飾品設計、商品說明、PSD 匯入對應、育種建議、環境反應規則） ================= */
/* 可以一次產生多個的 AI */
const AI_MULTI=new Set(['locus','allele','epi','poly','hab','zone','item','palslot','folder','ind','accd','biome','abyss']);
let AI_X='';
const aiX=()=>AI_X?`\n這次的特別指示（請優先遵守，但不可違反輸出格式與命名規則）：${AI_X}\n`:'';
const aiAttr=(extra,name)=>(String(extra||'').match(new RegExp(name+'="([^"]*)"'))||[])[1]||'';
const aiKeyOf=(kind,extra)=>[kind,aiAttr(extra,'data-i'),aiAttr(extra,'data-ref'),aiAttr(extra,'data-kvp')].filter(Boolean).join('-');
/* 常用指示的歸類：欄位裡的 AI 依欄位種類、商品說明依商品種類，其他依 AI 種類 */
