/* ---- 新的 AI 功能 ---- */
Object.assign(AI_TASKS,{
 /* 飾品設計 */
 accd:async()=>{const r=await ask(`設計 1 件飾品商品（給個體穿戴的裝飾），與現有飾品不同。可穿戴位置只能從這些${TERMS.code}選 1～2 個：${STORE.wear.map(w=>w.k+'='+w.n).join('、')}。現有飾品：${STORE.acc.map(a=>a.name+(a.kind?'（'+a.kind+'）':'')).join('、')||'無'}。`,'{"name":"繁中名","en":"English 名稱","kind":"類別（例如帽子、項圈、翼飾）","slots":["穿戴位置'+TERMS.code+'"],"desc":"一兩句商品說明","kw":"關鍵字，以頓號分隔","price":""}');
  const ids=new Set(STORE.acc.map(a=>a.id));const ks=new Set(STORE.wear.map(w=>w.k));let slots=(Array.isArray(r&&r.slots)?r.slots:[]).map(String).filter(k=>ks.has(k));if(!slots.length&&STORE.wear[0])slots=[STORE.wear[0].k];
  const a=normAcc({id:uniqId('AC',ids),name:String(r&&r.name||'新飾品'),en:String(r&&r.en||''),kind:String(r&&r.kind||''),slots,species:[],desc:String(r&&r.desc||''),price:String(r&&r.price||''),kw:kwList(String(r&&r.kw||''))});
  STORE.acc.push(a);UI.lvEd=UI.lvEd||{};UI.lvEd.acc=a.id;return`已新增飾品「${a.name}」，已展開可修改。`;},
 /* 商品說明（棲息地、道具、飾品） */
 cdesc:async(i,btn)=>{const ref=btn&&btn.dataset.ref;const c=catRef(ref);if(!c)throw{code:'_bad',message:'找不到商品'};const cat=String(ref).split('|')[0];
  const kindN={hab:'棲息地（加購商品）',item:'育種道具',acc:'飾品'}[cat]||'商品';let facts={};
  if(cat==='hab'){const z=(S.zones||[]).find(x=>x.id===c.zone),t=(S.biomes||[]).find(x=>x.id===c.type);facts={名稱:c.name,English:c.en||'',區域:z?z.n:'',類型:t?t.n:'',環境:Object.entries(c.f||{}).map(([k,v])=>k+'='+v).join('、'),效果:(()=>{try{return habSummary(c).replace(/<[^>]+>/g,' ');}catch(e){return'';}})()};}
  else if(cat==='item'){facts={名稱:c.name,類型:c.kind||'',效果:(()=>{try{return describeItem(c.rules||'').replace(/<[^>]+>/g,' ');}catch(e){return c.rules||'';}})()};}
  else facts={名稱:c.name,English:c.en||'',類別:c.kind||'',可穿戴位置:(c.slots||[]).map(k=>(STORE.wear.find(w=>w.k===k)||{}).n||k).join('、')};
  const r=await ask(`為${kindN}「${c.name}」寫給顧客看的商品說明，2～3 句，繁體中文，有商品感但不誇大；說明特色與用途，不要列出數值或規則原文。目前說明：${c.desc||'無'}。資料：${JSON.stringify(facts)}`,'{"desc":"商品說明"}',{modelTier:'quick'});
  c.desc=String(r&&r.desc||c.desc||'');return`已更新「${c.name}」的商品說明。`;},
 /* 環境反應規則 */
 envrules:async()=>{const r=await ask(`為這個物種撰寫或補充「物種環境反應規則」，讓環境因子合理地影響現有基因與多基因性狀。只寫新的規則，不要重複現有規則。${ENV_SYNTAX}\n因子：${(S.factors||[]).map(f=>`${f.id} ${f.name}（${f.unit||''}，基準 ${f.ref}，尺度 ${f.scale}）`).join('、')}\n目前規則：\n${S.envRules||'無'}`,'{"rules":"多行文字，每行一條，可在行尾加 # 註解","note":"一句話說明"}');
  const have=new Set(String(S.envRules||'').split('\n').map(x=>x.replace(/#.*/,'').trim()).filter(Boolean));const add=String(r&&r.rules||'').split('\n').map(x=>x.trim()).filter(x=>{const k=x.replace(/#.*/,'').trim();if(!k||have.has(k))return false;have.add(k);return true;});
  if(!add.length)return'AI 沒有提出新的規則。';S.envRules=(String(S.envRules||'').replace(/\s+$/,'')+'\n'+add.join('\n')).trim();const bad=parseEnv(S.envRules).bad.length;
  return`已加入 ${add.length} 條環境反應規則${r&&r.note?'：'+r.note:''}${bad?`（有 ${bad} 行格式無法辨識，請檢查）`:''}。`;},
 /* PSD 匯入對應：只補還沒對應到的群組與圖層 */
 lookmap:async()=>{const P=LOOK_PEND;if(!P)throw{code:'_bad',message:'沒有待確認的匯入'};const parts=looksCfg().parts.map(x=>({key:x.key,n:x.n,al:x.al||[]}));
  const rows=P.rows.map((r,i)=>({i,k:r.k,name:r.name,path:r.path,cur:r.pt?(lookPart(r.pt)||{}).key:'',eff:r.k==='l'?((lookPart(lookRowPart(i))||{}).key||''):''})).filter(r=>r.k!=='a');
  const r=await AI.json(`你在協助把 PSD 的群組與圖層對應到原創物種「${spLabel(S)}」的身體部位。名稱通常是繪師自己取的，可能是中文、英文、縮寫或數字；「遠／後／far／back」通常是離觀者較遠的一側，「近／前／near／front」是較近的一側；群組指定了部位，裡面的圖層會一起套用，所以優先給群組指定部位。只為還沒有部位的列（cur 與 eff 都是空字串）提出建議，無法判斷的就留空。用途：n 原圖、line 線稿、fill 單色填滿、tint 染色、hue 換色、shade 陰影、light 亮部；只有圖層名稱明顯表示用途時才填。${aiX()}\n部位：${JSON.stringify(parts)}\n色票部位：${palSlots().map(s=>s.k+'='+s.n).join('、')}\n列（i 為列號，k=g 群組、l 圖層）：${JSON.stringify(rows)}\n只回覆 JSON：{"map":[{"i":列號,"part":"部位 key 或空字串","role":"用途或空字串","pk":"色票部位${TERMS.code}或空字串"}],"note":"一句話"}`,{cache:false,modelTier:'quick'});
  let n=0;const byKey=k=>looksCfg().parts.find(x=>x.key===k);const roles=new Set(LOOK_ROLES.map(x=>x[0]));const pks=new Set(palSlots().map(s=>s.k));
  (Array.isArray(r&&r.map)?r.map:[]).forEach(m=>{const row=P.rows[+m.i];if(!row||row.k==='a')return;const pt=byKey(String(m.part||''));
   if(pt&&!row.pt&&(row.k==='g'||!lookRowPart(+m.i))){row.pt=pt.id;n++;}
   if(row.k==='l'&&row.role==='n'&&roles.has(m.role)&&m.role!=='n'){row.role=m.role;if(LOOK_COLROLES.has(m.role))row.pk=pks.has(m.pk)?m.pk:(row.pk||(palSlots()[0]||{}).k||'');}});
  return n?`AI 推測了 ${n} 個對應${r&&r.note?'（'+r.note+'）':''}，請確認後按「確認匯入」。`:'AI 沒有找到可以確定的對應，請手動選擇。';},
 /* 育種建議：AI 把目標轉成條件與多代計畫，實際機率由遺傳引擎逐對計算 */
 bplan:async()=>{const B=UI.bp=UI.bp||{};const goal=String(B.goal||'').trim();if(!goal)throw{code:'_bad',message:'請先寫下想培育的目標'};
  const r=await ask(`使用者想培育：「${goal}」。請把目標轉成這個網站的條件語法，並寫一份多代育種計畫。條件語法：基因^等位:hom（純合）／:het（異型）／:any（帶有），基因=等位（表現出來）、多基因=分級名稱，多個條件用 & 連接，只能用現有基因座與等位；多基因性狀的範圍放在 poly（id 為多基因${TERMS.code}，min／max 可只填一個）。計畫請條列 3～6 步，可以提到需要先做的過渡配對，以及要留意的致死或近親問題。`,`{"cond":"條件，可空字串","poly":[{"id":"多基因${TERMS.code}","min":null,"max":null}],"note":"一句話說明你怎麼理解目標","plan":"多代育種計畫（繁體中文，每步一行）"}`);
  B.res={cond:String(r&&r.cond||''),poly:(Array.isArray(r&&r.poly)?r.poly:[]).filter(p=>p&&S.poly.some(q=>q.id===p.id)).map(p=>({id:p.id,min:p.min==null||p.min===''?null:+p.min,max:p.max==null||p.max===''?null:+p.max})),note:String(r&&r.note||''),plan:String(r&&r.plan||''),pairs:null};
  await bpCompute();const top=(B.res.pairs||[])[0];return top&&top.p>0?`已找出 ${B.res.pairs.length} 組配對，最佳一組達成機率約 ${(top.p*100).toFixed(1)}%。`:'目前的個體一代內無法達成，請參考多代計畫。';}
});
