function assetGcRun(final){if(!AGC.q.size||!ASSETS)return;if(typeof CLOUD!=='undefined'&&(CLOUD.loading||CLOUD.mode==='visitor')){clearTimeout(AGC.t);AGC.t=setTimeout(()=>assetGcRun(final),30000);return;}
 let live='';try{live=JSON.stringify(STORE);}catch(e){return;}const hist=final||typeof GU==='undefined'?[]:[...GU.undo,...GU.redo].map(e=>e.snap||'');
 [...AGC.q].forEach(id=>{if(live.includes(id)){AGC.q.delete(id);return;}if(hist.some(s=>s.includes(id)))return;ASSETS.delete(id).catch(()=>{});AGC.q.delete(id);});agcSave();}
if(typeof window!=='undefined'&&window.addEventListener){window.addEventListener('pagehide',()=>{try{assetGcRun(true);}catch(e){}});setTimeout(()=>{try{assetGcRun(false);}catch(e){}},45000);}
