/* ---- 共用：多圖層依序合成（剪裁、混合模式、不透明度、上色） ---- */
function lookStack(x,L,ims,pal,sc,W,Hh){for(let i=0;i<L.length;i++){const l=L[i];if(l.clip)continue;let j=i+1;const clips=[];while(j<L.length&&L[j].clip){clips.push(j);j++;}
  if(l.hid||!ims[i])continue;const lc=lookLayerCanvas(l,ims[i],pal,sc);
  if(clips.length){const t=document.createElement('canvas');t.width=W;t.height=Hh;const tx=t.getContext('2d');tx.drawImage(lc,Math.round(l.x*sc),Math.round(l.y*sc));
   clips.forEach(k=>{const cl=L[k];if(cl.hid||!ims[k])return;tx.globalCompositeOperation='source-atop';tx.globalAlpha=cl.op==null?1:cl.op;const cc=lookLayerCanvas(cl,ims[k],pal,sc);
    if(lookOp(cl)!=='source-over'){const u=document.createElement('canvas');u.width=W;u.height=Hh;const ux=u.getContext('2d');ux.drawImage(t,0,0);ux.globalCompositeOperation=lookOp(cl);ux.globalAlpha=tx.globalAlpha;ux.drawImage(cc,Math.round(cl.x*sc),Math.round(cl.y*sc));ux.globalCompositeOperation='destination-in';ux.globalAlpha=1;ux.drawImage(lc,Math.round(l.x*sc),Math.round(l.y*sc));tx.globalCompositeOperation='copy';tx.globalAlpha=1;tx.drawImage(u,0,0);}
    else tx.drawImage(cc,Math.round(cl.x*sc),Math.round(cl.y*sc));});
   x.globalCompositeOperation=lookOp(l);x.globalAlpha=l.op==null?1:l.op;x.drawImage(t,0,0);}
  else{x.globalCompositeOperation=lookOp(l);x.globalAlpha=l.op==null?1:l.op;x.drawImage(lc,Math.round(l.x*sc),Math.round(l.y*sc));}
  x.globalCompositeOperation='source-over';x.globalAlpha=1;}
}

