/* ================= 第 56 版：基因變更紀錄＋匯入自動補救 ================= */
/* S.geneLog=[{rev,at,k:'ren'|'del',sym,al(null＝整個基因座),to,note}]，S.geneRev＝目前的變更次數。
   改名、刪除基因座或等位時自動記一筆（刪除等位的 to＝舊檔案裡的它要換成哪個等位，預設當時的野生型，可在「變更紀錄」修改）。
   匯出的個體檔標上 gr（匯出當時的變更次數）。匯入個體檔、外部個體、公開試算的「我的個體」時，只套用 gr 之後的變更：
   舊符號翻成新符號、被刪的等位換成指定的等位、被刪的基因座移除，並列出調整了什麼。沒有 gr 的舊檔案從第 0 次開始套用。
   完整備份與匯入物種是整份快照（基因庫和個體一起），不需要翻譯。 */
const geneRevOf=sp=>+((sp||S).geneRev)||0;
const geneLogR=sp=>Array.isArray((sp||S).geneLog)?(sp||S).geneLog:[];
function geneLogAdd(){var f=ghRestGet("geneLogAdd");return new.target?Reflect.construct(f,arguments):f.apply(this,arguments);}geneLogAdd.__rs=1;
/* 依變更紀錄翻譯一隻個體（只動基因相關欄位），回傳調整說明 */
function geneTrans(o,fromRev,log){const notes=[];if(!o)return notes;const L=(log||[]).filter(e=>+e.rev>(+fromRev||0)).sort((a,b)=>a.rev-b.rev);if(!L.length)return notes;
 const g=o.g&&typeof o.g==='object'?o.g:(o.g={});
 const keyMap=(obj,fn)=>{if(!obj||typeof obj!=='object')return;Object.keys(obj).forEach(k=>{const pre=k.startsWith('pen:')?'pen:':'';const kk=k.slice(pre.length);if(!kk.includes('^'))return;const r=fn(kk);if(r===kk)return;const v=obj[k];delete obj[k];if(r)obj[pre+r]=v;});};
 L.forEach(e=>{const sym=e.sym,al=e.al;
  if(e.k==='ren'&&al==null){if(g[sym]!=null){g[e.to]=g[sym];delete g[sym];notes.push(`${sym}→${e.to}`);}if(o.gm&&o.gm[sym]){o.gm[e.to]=o.gm[sym];delete o.gm[sym];}
   ['ipen','epi'].forEach(f=>keyMap(o[f],k=>{const [s,...r]=k.split('^');return s===sym?e.to+'^'+r.join('^'):k;}));if(Array.isArray(o.np))o.np=o.np.map(x=>x===sym?e.to:x);}
  else if(e.k==='ren'){const a=g[sym];if(Array.isArray(a)&&a.includes(al)){g[sym]=a.map(x=>x===al?e.to:x);notes.push(`${sym}^${al}→${sym}^${e.to}`);}if(o.gm&&Array.isArray(o.gm[sym]))o.gm[sym]=o.gm[sym].map(x=>x===al?e.to:x);
   ['ipen','epi'].forEach(f=>keyMap(o[f],k=>k===sym+'^'+al?sym+'^'+e.to:k));}
  else if(e.k==='merge'){/* 第 197 版：基因座 sym 併進 to（map＝sym 的等位 → to 的等位，wa＝to 的野生型） */const b=g[sym];const w=e.wa||'+';const M=e.map||{};
   if(Array.isArray(b)){const a=Array.isArray(g[e.to])?g[e.to]:b.map(x=>x==null?null:w);const r=v197Comb(a,b.map(x=>x==null?null:(M[x]||w)),w);g[e.to]=r.g;delete g[sym];notes.push(`${sym}→${e.to}${r.lost.length?'（'+r.lost.join('、')+' 放不下）':''}`);}
   if(o.gm)delete o.gm[sym];['ipen','epi'].forEach(f=>keyMap(o[f],k=>{const [s,...r]=k.split('^');if(s!==sym)return k;const x=r.join('^');return e.to+'^'+(M[x]||x);}));if(Array.isArray(o.np))o.np=[...new Set(o.np.map(x=>x===sym?e.to:x))];}
  else if(e.k==='del'&&al==null){if(g[sym]!=null){delete g[sym];notes.push(`移除已刪除的基因座 ${sym}`);}if(o.gm)delete o.gm[sym];['ipen','epi'].forEach(f=>keyMap(o[f],k=>k.split('^')[0]===sym?'':k));if(Array.isArray(o.np))o.np=o.np.filter(x=>x!==sym);}
  else if(e.k==='del'){const a=g[sym];const to=e.to||null;if(Array.isArray(a)&&a.includes(al)){g[sym]=a.map(x=>x===al?to:x);notes.push(`${sym}^${al}→${to?sym+'^'+to:'野生型'}`);}if(o.gm&&Array.isArray(o.gm[sym]))o.gm[sym]=o.gm[sym].map(x=>x===al?'':x);
   ['ipen','epi'].forEach(f=>keyMap(o[f],k=>k===sym+'^'+al?'':k));}});
 return notes;}
