/* ---- 公開試算：我的個體 ---- */
function calcGlog(){try{const sp=calcSpecies();return sp&&sp.glog?sp.glog:null;}catch(e){return null;}}
function calcTransOwn(){const G=calcGlog();if(!G||!G.rev)return'';let n=0;const cnt=new Map();(CALC.own||[]).forEach(x=>{const from=x.gr==null?0:+x.gr;if(from>=G.rev)return;const ns=geneTrans(x,from,G.log);x.gr=G.rev;if(ns.length){n++;ns.forEach(t=>cnt.set(t,(cnt.get(t)||0)+1));}});
 if(!n)return'';return`已依基因變更紀錄調整 ${n} 隻：${[...cnt.entries()].map(([t,c])=>`${t}（${c}）`).slice(0,6).join('、')}`;}
