/* ================= 第 164 版（2026-11-09）：水印鑲嵌在物件範圍內 ================= */
/* 使用者要求：水印做在圖片裡（有顏色的地方）＋預覽頁自己一層；物件「範圍內」的透明處也要有字，範圍外不要。
   第 163 版把整張 GIF 鋪滿字：跟著圖片一起移動、露出長方形的邊、檔案也變大，所以拿掉。
   做法：畫面產生後，在每一格「透明、但在物件範圍內」的地方補字（destination-over，只會出現在透明處）。不存檔，圖片容量不變。
   範圍＝不透明的地方，先合起窄縫（closing，半徑是長邊的 6%），再填滿被包住的洞。 */
/* 第 165 版：為了載入速度，一組畫面只算一張遮罩（取幾格的聯集）、精度降低、不等字型 */
const TPV_RANGE_N=120,TPV_RANGE_R=.06;
/* 物件範圍（小張的遮罩，用的時候放大）；整張透明回傳 null */
function tpvRangeMask(src){const sc=Math.min(1,TPV_RANGE_N/Math.max(src.width,src.height));const w=Math.max(1,Math.round(src.width*sc)),h=Math.max(1,Math.round(src.height*sc));const s=document.createElement('canvas');s.width=w;s.height=h;const x=s.getContext('2d',{willReadFrequently:true});x.drawImage(src,0,0,w,h);const im=x.getImageData(0,0,w,h);const d=im.data,n=w*h;
 const on=new Uint8Array(n);let any=false;for(let i=0;i<n;i++)if(d[i*4+3]>24){on[i]=1;any=true;}if(!any)return null;
 /* 到最近種子的距離（直向 3、斜向 4）；畫布外不算種子，貼著畫布邊的物件不會被侵蝕 */
 const dist=seed=>{const D=new Int32Array(n);for(let i=0;i<n;i++)D[i]=seed(i)?0:1e8;for(let y=0,i=0;y<h;y++)for(let k=0;k<w;k++,i++){let m=D[i];if(k)m=Math.min(m,D[i-1]+3);if(y){m=Math.min(m,D[i-w]+3);if(k)m=Math.min(m,D[i-w-1]+4);if(k<w-1)m=Math.min(m,D[i-w+1]+4);}D[i]=m;}for(let y=h-1,i=n-1;y>=0;y--)for(let k=w-1;k>=0;k--,i--){let m=D[i];if(k<w-1)m=Math.min(m,D[i+1]+3);if(y<h-1){m=Math.min(m,D[i+w]+3);if(k<w-1)m=Math.min(m,D[i+w+1]+4);if(k)m=Math.min(m,D[i+w-1]+4);}D[i]=m;}return D;};
 const r=Math.max(1,Math.round(Math.max(w,h)*TPV_RANGE_R));const A=dist(i=>on[i]);const grown=new Uint8Array(n);for(let i=0;i<n;i++)grown[i]=A[i]<=3*r?1:0;const B=dist(i=>!grown[i]);const keep=new Uint8Array(n);/* 多縮一格：遮罩放大後邊緣比較軟，字不會超出物件外緣 */for(let i=0;i<n;i++)keep[i]=B[i]>3*(r+1)||on[i]?1:0;
 /* 從畫布邊往內灌，灌不到的透明處＝被包住的洞 */
 const out=new Uint8Array(n);const st=[];const push=i=>{if(!keep[i]&&!out[i]){out[i]=1;st.push(i);}};for(let k=0;k<w;k++){push(k);push(n-w+k);}for(let y=0;y<h;y++){push(y*w);push(y*w+w-1);}while(st.length){const i=st.pop();const k=i%w;if(k)push(i-1);if(k<w-1)push(i+1);if(i>=w)push(i-w);if(i<n-w)push(i+w);}
 for(let i=0;i<n;i++){d[i*4]=d[i*4+1]=d[i*4+2]=255;d[i*4+3]=out[i]?0:255;}x.putImageData(im,0,0);return s;}
/* 字的大小：照畫面長邊；像素版畫面小，最少照 480 算，放大後才看得出是字 */
const tpvRangeU=(w,h)=>Math.max(480,w,h);
/* 整張字（同一份水印樣式）。solid＝GIF 用：GIF 只有全透明和不透明，半透明的字會消失，先和深色混好再用不透明畫 */
const TPV_RT={k:'',c:null};
function tpvRangeSolid(){var f=ghRestGet("tpvRangeSolid");return new.target?Reflect.construct(f,arguments):f.apply(this,arguments);}tpvRangeSolid.__rs=1;
async function tpvRangeText(W,H,U,C0,solid){const C={...C0,fw:100};const F0=TPV_FONTS.find(f=>f[0]===C.font)||TPV_FONTS[0];let fok=true;try{fok=document.fonts.check(`${F0[3]} 16px ${F0[2]}`);}catch(e){}const k=JSON.stringify([W,H,U,C,!!solid,fok]);if(TPV_RT.k===k&&TPV_RT.c)return TPV_RT.c;const c=document.createElement('canvas');c.width=W;c.height=H;const x=c.getContext('2d');const op=Math.min(1,Math.max(.05,+C.opB||.42));
 if(solid)await tpvDraw(x,W,H,0,0,U,{...C,color:tpvRangeSolid(C)},'source-over',C.img?Math.max(.55,op):1);else{x.shadowColor='rgba(0,0,0,.45)';x.shadowOffsetX=1;x.shadowOffsetY=1;x.shadowBlur=0;await tpvDraw(x,W,H,0,0,U,C,'source-over',op);}TPV_RT.k=k;TPV_RT.c=c;return c;}
/* 把字裁到物件範圍：T＝整張字，m＝遮罩 */
function tpvRangeCut(T,m){const t=document.createElement('canvas');t.width=T.width;t.height=T.height;const q=t.getContext('2d');q.drawImage(T,0,0);q.globalCompositeOperation='destination-in';q.imageSmoothingEnabled=true;q.imageSmoothingQuality='high';q.drawImage(m,0,0,T.width,T.height);return t;}
/* 補到一格畫面（只會出現在透明處） */
function tpvRangeOver(c,t){const x=c.getContext('2d');x.save();x.globalCompositeOperation='destination-over';x.drawImage(t,0,0);x.restore();}
/* 整組畫面補字：o.C 樣式、o.U 字的基準、o.solid 給 GIF；F.wmT＝裁好的字，留給拖曳視角時重畫用 */
async function tpvRangeFrames(F,o){o=o||{};const L=F&&F.frames;if(!L||!L.length)return;const W=L[0].width,H=L[0].height;const T=await tpvRangeText(W,H,o.U||F.wmU||tpvRangeU(W,H),o.C||tpvPubCfg(),o.solid);/* 同一張畫布可能重複出現（靜止的格），只補一次 */const fr=[...new Set(L)];
 const sc=Math.min(1,TPV_RANGE_N/Math.max(W,H));const u=document.createElement('canvas');u.width=Math.max(1,Math.round(W*sc));u.height=Math.max(1,Math.round(H*sc));const ux=u.getContext('2d');const st=Math.max(1,Math.floor(fr.length/4));for(let i=0;i<fr.length;i+=st)ux.drawImage(fr[i],0,0,u.width,u.height);
 const m=tpvRangeMask(u);if(!m)return;const t=tpvRangeCut(T,m);/* 第 200 版：o.noDraw＝影格上已經印好了（匯出時先算好的），只留裁好的字給重畫用 */if(!o.noDraw)fr.forEach(c=>tpvRangeOver(c,t));F.wmT=t;}
