 for(let x=x0+6;x<x1;x+=12){const t=ty(x);r+=`<line x1="${x}" y1="${(cy+A*Math.sin(t)).toFixed(1)}" x2="${x}" y2="${(cy-A*Math.sin(t)).toFixed(1)}" opacity="${(.2+.6*Math.abs(Math.cos(t))).toFixed(2)}"/>`;}
