  /* 第 161 版：標語從條碼區塊拆出來，自己是一個圖層 */{const bh=U*110;el('tag',colX,H-U*40-U*120+bh*.72,colW,bh*.28,(x,w,h)=>{x.save();pstFont(x,`400 {s} ${PF.mono}`,Math.round(tiny*.8));x.fillStyle=sub;x.textAlign='right';x.fillText(String(T.tag).toUpperCase(),w,bh*.18);x.restore();});}
  if(G)el('list',G[0],G[1],G[2],G[3],(x,w,h)=>{x.save();const cols=land?(wide?2:1):Math.min(n,6),rows=Math.ceil(n/cols);const gap=Math.min(w,h)*.05;const lab=tiny*2.4;const cw=Math.min((w-gap*(cols-1))/cols,land?w:W*.12);const ch=Math.min(cw,(h-rows*lab-gap*(rows-1))/rows);
    const oy=land&&!wide?Math.max(0,(h-(rows*(ch+lab)+gap*(rows-1)))/2):0;
    L.slice(0,n).forEach((o,k)=>{const cx=(k%cols)*(cw+gap),cy=oy+Math.floor(k/cols)*(ch+lab+gap);x.fillStyle=C.cell;x.fillRect(cx,cy,cw,ch+lab);x.strokeStyle=C.line;x.lineWidth=Math.max(1,U*1.1);x.strokeRect(cx+.5,cy+.5,cw-1,ch-1);
     if(o.cv){const s=Math.min((cw-8)/o.cv.width,(ch-8)/o.cv.height);x.drawImage(o.cv,cx+(cw-o.cv.width*s)/2,cy+(ch-o.cv.height*s)/2,o.cv.width*s,o.cv.height*s);}
     x.fillStyle=sub;pstLs(x,`${tiny*.18}px`);pstFont(x,`700 {s} ${PF.mono}`,Math.round(tiny*.72));x.fillText(`${String(k+1).padStart(2,'0')} ${String(o.slot||'').toUpperCase()}`.slice(0,22),cx,cy+ch+tiny*1.05);
     pstLs(x,'0px');pstFit(x,o.a.name||'',`italic 500 {s} ${PF.bod}`,Math.round(tiny*1.05),cw);x.fillStyle=ink;x.fillText(o.a.name||'',cx,cy+ch+tiny*2.2);});x.restore();});
  /* 第 161 版：這一行是字詞（原本 id 叫 tag） */el('words',U*50,U*36,B.rule[0]-U*100,U*50,(x,w,h)=>{x.save();pstLs(x,`${tiny*.2}px`);pstFont(x,`400 {s} ${PF.mono}`,Math.round(tiny*.75));x.fillStyle=sub;x.fillText(`${(T.words||[]).slice(0,6).join(' · ')}`.slice(0,80),0,tiny);x.restore();});
  el('s1',W-U*50-U*40,iY+U*230,U*40,U*40,(x,w,h)=>{x.save();x.strokeStyle=ink;x.lineWidth=Math.max(1,w*.04);x.translate(w/2,h/2);x.scale(w/100,h/100);x.translate(-50,-50);x.stroke(PSTAR.t);x.restore();});
