/* 兩種風格都用「像素格」畫：短邊約 270 格（1080 寬＝每格 4 像素），每個元素先畫在低解析度畫布再用最近點放大，字的透明度二值化（沒有灰邊）；
   顏色少、邊緣硬，GIF 的檔案也小。小房間素材時棲息地與生物分開放（T.layers 決定要哪幾層，見 1099）；試穿圖素材時把生物圖縮成像素格。 */
const PXF={lab:'"Silkscreen","VT323","DotGothic16","Noto Sans TC",monospace',txt:'"DotGothic16","VT323","Noto Sans TC",sans-serif'};
const pxU=(W,H)=>Math.max(1,Math.min(W,H)/270);
function pxRgb(){var f=ghRestGet("pxRgb");return new.target?Reflect.construct(f,arguments):f.apply(this,arguments);}pxRgb.__rs=1;
const pxMix=(a,b,t)=>{const A=pxRgb(a),B=pxRgb(b);return'#'+A.map((v,i)=>Math.round(v+(B[i]-v)*t).toString(16).padStart(2,'0')).join('');};
/* 元素先畫在低解析度畫布（每格 u 像素），再放大到元素大小 */
function pxEl(){var f=ghRestGet("pxEl");return new.target?Reflect.construct(f,arguments):f.apply(this,arguments);}pxEl.__rs=1;
const pxQ=()=>pxText.q||(pxText.q=pstCv(8,8).getContext('2d'));
const pxFont=o=>`${o.w||400} ${Math.max(5,Math.round(o.s||8))}px ${o.f||PXF.txt}`;
function pxW(){var f=ghRestGet("pxW");return new.target?Reflect.construct(f,arguments):f.apply(this,arguments);}pxW.__rs=1;
/* 像素字：o＝{s 字級, c 顏色, f 字型, w 粗細, a 對齊 left／center／right, ls 字距}；回傳寬度 */
function pxText(g,t,X,Y,o){o=o||{};t=String(t==null?'':t);if(!t)return 0;const s=Math.max(5,Math.round(o.s||8));const tw=Math.ceil(pxW(t,o))+2,th=Math.ceil(s*1.4)+2;
 const c=pstCv(tw,th);const q=c.getContext('2d',{willReadFrequently:true});q.font=pxFont(o);pstLs(q,`${o.ls||0}px`);q.textBaseline='top';q.fillStyle='#000';q.fillText(t,1,1);
 const id=q.getImageData(0,0,tw,th);const d=id.data;const [r,gg,b]=pxRgb(o.c);for(let i=0;i<d.length;i+=4){d[i]=r;d[i+1]=gg;d[i+2]=b;d[i+3]=d[i+3]>=110?255:0;}q.putImageData(id,0,0);
 const ax=o.a==='right'?X-tw+1:o.a==='center'?X-Math.round(tw/2):X-1;g.drawImage(c,Math.round(ax),Math.round(Y)-1);return tw-2;}
