   const by=gy+rows*cs+2;g.fillStyle=C.acc;g.fillRect(cr.x,by+2,7,7);g.fillStyle=C.line;g.fillRect(cr.x+2,by+4,3,3);pxBox(g,cr.x+10,by,cr.w-10,11,C.line,C.head);
