/* 色票：混色以外的表現方式，第一個（主）等位是底色，第二個等位記成「~部位」＝種類|顏色|種子，合成時畫成花紋 */
(function(){if(typeof window==='undefined')return;const GP0=window.genePalette;if(typeof GP0!=='function')return;
 window.genePalette=function(ind,jitter){const ex=express(ind,ind.hab,false);const base={};palSlots().forEach(s=>base[s.k]=isHex(s.base)?s.base:'#cccccc');const pal={...base};const layers=[];const hx={};
  for(const l of S.loci){if(l.poly)continue;const ph=ex.loci[l.sym];if(!ph||ph.hidden)continue;const acc={};const kind=ph.exp.length>1&&ph.hx&&ph.hx!=='blend'?ph.hx:'';
   ph.exp.forEach((o,j)=>{const md=alBlend(l,o);Object.entries(parseCol(o.col)).forEach(([k,v])=>{if(md==='normal'){if(kind&&j>0){hx[k]={kind,c:v};return;}(acc[k]=acc[k]||[]).push(v);}else layers.push({k,v,md,opa:l.opa});});});
   if(kind){const c1=parseCol(ph.exp[0].col),c2=parseCol(ph.exp[1].col);if(alBlend(l,ph.exp[0])==='normal')Object.keys(c1).forEach(k=>{if(!(k in c2)&&!hx[k])hx[k]={kind,c:base[k]};});}
   Object.entries(acc).forEach(([k,v])=>{if(k in pal)pal[k]=mixHex(v);});}
  polyBandCol(ex,pal);ex.epi.forEach(r=>Object.entries(parseCol(r.col)).forEach(([k,v])=>{if(k in pal){pal[k]=v;delete hx[k];}}));
  layers.forEach(x=>{if(x.k in pal)pal[x.k]=blendHex(pal[x.k],x.v,x.md,x.opa);});polyTone(ex,pal);
  if(jitter)Object.keys(pal).forEach(k=>pal[k]=jitterHex(pal[k]));
  const seed=hashStr(String(ind.us||ind.id||'x'))%99991;Object.entries(hx).forEach(([k,o])=>{if(k in pal&&isHex(o.c)&&o.c.toLowerCase()!==String(pal[k]).toLowerCase())pal['~'+k]=`${o.kind}|${jitter?jitterHex(o.c):o.c}|${seed}`;});return pal;};})();
