AI_TASKS.v77rev=async i=>{const l=S.loci[+i];if(!l)throw{code:'_bad',message:'找不到基因座'};const vs=variantsOf(S);
 const data={sym:l.sym,name:l.name,mode:MODES[l.mode],chr:ctype(l),hx:l.hx||'自動',pairs:l.hxp||'',labels:l.labels||'',alleles:l.alleles.map(a=>({s:a.s,n:a.n,rank:+a.rank||0,f:+a.f||0,vf:a.vf||{},pen:a.pen,leth:!!a.leth,col:a.col||''})),
  lint:v77Lint(l,+i).map(x=>x.t),preview:Object.fromEntries(vs.map(v=>[v.code,[...v77Dist(l,v.code,'F').entries()].sort((a,b)=>b[1].p-a[1].p).slice(0,8).map(([k,o])=>`${k} ${(o.p*100).toFixed(1)}%`)])),subspecies:vs.map(v=>`${v.code} ${v.name||''}：${v.desc||''}`)};
 const r=await ask(`以遺傳學、發育生物學與生態學的角度檢查這個基因座的設定是否合理，並提出更貼近真實現象的修改建議（顯性模式、異型合子表現方式、頻率與亞種差異、致死、命名）。異型合子表現方式可選：${HX_KINDS.map(k=>k[0]+'＝'+k[1]).join('、')}。基因座資料：${JSON.stringify(data)}`,
  `{"verdict":"一兩句總評","issues":[{"t":"問題","fix":"建議做法"}],"mode":"dom/codom/inc 或空字串（維持）","hx":"表現方式 key 或空字串","pairs":[{"pair":"a/b","kind":"表現方式 key","zh":"中文名稱或空字串","en":"English name 或空字串"}]}`);
 const o={verdict:String(r&&r.verdict||'').slice(0,400),issues:(Array.isArray(r&&r.issues)?r.issues:[]).slice(0,10).map(x=>({t:String(x&&x.t||'').slice(0,300),fix:String(x&&x.fix||'').slice(0,300)})),
  mode:MODES[r&&r.mode]?r.mode:'',hx:HX_BY[r&&r.hx]?r.hx:'',pairs:(Array.isArray(r&&r.pairs)?r.pairs:[]).map(x=>({pair:String(x&&x.pair||''),kind:hxNorm(x&&x.kind),zh:String(x&&x.zh||'').slice(0,40),en:String(x&&x.en||'').slice(0,60)})).filter(x=>{const p=x.pair.split('/');return p.length===2&&p.every(s=>l.alleles.some(a=>a.s===s.trim()));}).slice(0,40)};
 UI.v77ai=UI.v77ai||{};UI.v77ai[l.sym]=o;UI.v77o=UI.v77o||new Set();UI.v77o.add(+i);UI.openLoc=+i;return`已檢查 ${l.sym} ${l.name}：${o.issues.length} 個建議，結果在「理論檢查與設定建議」。`;};
