  if(t.dataset.v77c){e.stopImmediatePropagation();UI.v77c=UI.v77c||{};UI.v77c[t.dataset.v77c]=t.value;const b=t.closest('[data-v77p]');if(b)b.innerHTML=v77Body(+b.dataset.v77p);return;}
