(function(){if(typeof window==='undefined')return;const TN0=window.tradeName;if(typeof TN0!=='function')return;
 window.tradeName=function(ind,res,hide,opt){const R=((res&&res.epi)||[]).filter(r=>r.ren);if(!R.length)return TN0.apply(this,arguments);const ren=new Set(R.flatMap(r=>String(r.ren).split(/[,\s]+/).filter(Boolean)));
  /* 組合名稱放在第一個新基因座的位置（和拆解前的名稱順序相同），其他新基因座的名稱不顯示 */
  const loci={...res.loci};const used=new Set(),hosts=new Set();const bySlot=new Map();R.forEach(r=>{if(!bySlot.has(r.slot))bySlot.set(r.slot,[]);bySlot.get(r.slot).push(r);});
  bySlot.forEach((rs,slot)=>{const h=S.loci.find(l=>ren.has(l.sym)&&!hosts.has(l.sym)&&l.slot===slot&&loci[l.sym]&&!loci[l.sym].hidden&&!(hide&&hide.has(l.sym)));if(!h)return;const en=rs.map(r=>r.en).filter(Boolean);if(!en.length)return;
   hosts.add(h.sym);rs.forEach(r=>used.add(r));loci[h.sym]={...loci[h.sym],en:en.join(' '),zh:rs.map(r=>r.zh||r.en).filter(Boolean).join('·'),ov:true};});
  ren.forEach(s=>{if(loci[s]&&!loci[s].hidden&&!hosts.has(s))loci[s]={...loci[s],hidden:'ren'};});const out=TN0.call(this,ind,{...res,loci,epi:res.epi.filter(r=>!used.has(r))},hide,opt);
  const names=new Set();const het=out.het||(out.het=[]);ren.forEach(s=>{const l=S.loci.find(x=>x.sym===s);const ph=res.loci[s];if(!l||!ph||ph.hidden||hosts.has(s))return;l.alleles.forEach(a=>{if(a.en)names.add(a.en);});const wild=l.alleles[0]&&l.alleles[0].s;const exp=ph.exp.map(o=>o.s);
  presOf(ind,l).forEach(a=>{const o=IDX.al[s][a];if(o&&a!==wild&&o.en&&!exp.includes(a)&&!het.includes(o.en))het.push(o.en);});});out.masked=(out.masked||[]).filter(x=>!names.has(x));return out;};})();
{const GP=genePalette;genePalette=function(ind,jitter){const pal=GP.apply(this,arguments);try{const ex=express(ind,ind.hab,false);ex.epi.forEach(r=>{if(!r.gen||!r.col)return;Object.entries(parseCol(r.col)).forEach(([k,v])=>{if(k in pal&&isHex(v))pal[k]=jitter?jitterHex(v):v;});});}catch(e){}return pal;};}
