function rmNear2(P,r,g,b){let a0=0,a1=0,d0=1e12,d1=1e12;for(let i=0;i<P.length;i++){const q=P[i];const d=(q[0]-r)**2+(q[1]-g)**2+(q[2]-b)**2;if(d<d0){d1=d0;a1=a0;d0=d;a0=i;}else if(d<d1){d1=d;a1=i;}}return[a0,a1,d0,d1];}

/* src：4 倍大的 canvas；回傳 w×h 的 ImageData */
/* 第 190 版：o.sd＋o.box＝[x,y,寬,高]（小圖的像素）：只給那個範圍的 4 倍大資料（寬 box[2]*4），範圍外當透明 */
function rmPixelize(src,w,h,P,o){const thr=o.alo!=null?Math.min(110,+o.alo):110;const BX=o.box||[0,0,w,h];const sd=o.sd||src.getContext('2d').getImageData(0,0,w*4,h*4).data;const SW=BX[2]*4;const out=new ImageData(w,h);const od=out.data;const idx=new Int16Array(w*h).fill(-1);const B=[[0,2],[3,1]];
 const cnt=new Int32Array(P.length);
 for(let y=BX[1];y<BX[1]+BX[3];y++)for(let x=BX[0];x<BX[0]+BX[2];x++){cnt.fill(0);let ar=0,sr=0,sg=0,sb=0,no=0;
  for(let j=0;j<4;j++)for(let i=0;i<4;i++){const q=(((y-BX[1])*4+j)*SW+((x-BX[0])*4+i))*4;const al=sd[q+3];ar+=al;if(al>=thr){sr+=sd[q];sg+=sd[q+1];sb+=sd[q+2];no++;cnt[rmNear2(P,sd[q],sd[q+1],sd[q+2])[0]]++;}}
  ar/=16;let on;if(o.alo!=null&&o.ahi!=null){on=ar>=o.ahi||(ar>=o.alo&&(x+y)%2===0);}else on=ar>=110;if(!on||!no)continue;
  let m=0;for(let i=1;i<P.length;i++)if(cnt[i]>cnt[m])m=i;let pick=m;
  /* 第 145 版：o.avg＝生物立體網格用的貼圖：改成這一格最多的調色盤顏色、不打網點（第 126 版用平均色再照畫面打網點，平均色把線稿混進白毛，轉動時整隻偏色、帶點點；使用者回報色偏） */if(o.avg){const k=(y*w+x)*4,a=o.avg.data,c0=P[m];a[k]=c0[0];a[k+1]=c0[1];a[k+2]=c0[2];a[k+3]=255;}
  if(o.dstr>0){const [a0,a1,d0,d1]=rmNear2(P,sr/no,sg/no,sb/no);const t=Math.sqrt(d0)/(Math.sqrt(d0)+Math.sqrt(d1)+1e-6);if(t>.18)pick=(t*2*o.dstr>(B[y%2][x%2]/4+1/8))?a1:a0;}
  idx[y*w+x]=pick;}
 const cy0=Math.max(1,BX[1]),cy1=Math.min(h-1,BX[1]+BX[3]),cx0=Math.max(1,BX[0]),cx1=Math.min(w-1,BX[0]+BX[2]);
 for(let pass=0;pass<(o.clean||0);pass++){const c=idx.slice();for(let y=cy0;y<cy1;y++)for(let x=cx0;x<cx1;x++){const v=c[y*w+x];if(v<0)continue;const u=c[(y-1)*w+x],d=c[(y+1)*w+x],l=c[y*w+x-1],r=c[y*w+x+1];
  if(u>=0&&u===d&&u===l&&u===r&&v!==u&&!(c[(y-1)*w+x-1]===v&&c[(y+1)*w+x+1]===v))idx[y*w+x]=u;}}
 for(let y=BX[1];y<BX[1]+BX[3];y++)for(let x=BX[0];x<BX[0]+BX[2];x++){const i=y*w+x;const v=idx[i];if(v<0)continue;const p=P[v];od[i*4]=p[0];od[i*4+1]=p[1];od[i*4+2]=p[2];od[i*4+3]=255;}return out;}
/* ---- 骨架：讀這隻的部位圖 → 工作畫布上的每個部位（同一張畫布大小）＋轉軸＋父子 ---- */
const RM_CACHE=new Map();
/* 第 97 版：ind.__look＝試穿時的身體（模板、PSD 等，沒有存成個體分層圖的）；ind.__acc＝穿戴的飾品片段，插在部位之間、跟著穿戴部位動 */
async function rmRig(ind,mode){const R=rmCfg();const lk0=ind.__look||farmLook(ind);if(!lk0)throw new Error('這隻還沒有分層圖（部位圖）');const lk=ind.__acc&&ind.__acc.length?{...lk0,parts:amInsertAcc(lk0.parts,ind.__acc)}:lk0;
 const o=ind.room||{};const B=R.box;const size=amSizeOf(rmHabOf(ind),mode);const cw=Math.max(16,Math.round(size*(o.scale!=null?+o.scale:+B.scale)));
 const key=JSON.stringify([mode,cw,lk.parts.map(p=>[p.k,p.sig||p.u,p.x,p.y,p.w,p.h]),mode==='px'?R.px:0,lk.parts.map(p=>{const c=rmPartCfg(R,p,ind);return[c.alo,c.ahi];}),lk.w,lk.h]);
 if(RM_CACHE.has(key))return RM_CACHE.get(key);
 let x0=1e9,y0=1e9,x1=-1e9,y1=-1e9;lk.parts.forEach(p=>{x0=Math.min(x0,p.x);y0=Math.min(y0,p.y);x1=Math.max(x1,p.x+p.w);y1=Math.max(y1,p.y+p.h);});
 /* 生物的大小只看身體（飾品超出身體時畫布變大，生物不會變小） */let bx0=1e9,bx1=-1e9;lk.parts.forEach(p=>{if(p.acc)return;bx0=Math.min(bx0,p.x);bx1=Math.max(bx1,p.x+p.w);});if(bx1<=bx0){bx0=x0;bx1=x1;}
 const k=cw/(bx1-bx0),pad=Math.round(cw*.1);
 /* 第 189 版：部位圖很大時在背景解碼、直接縮到要畫的大小（amImgAt；像素版先畫 4 倍再減色） */const kd=k*(mode==='px'?4:1);const ims=await Promise.all(lk.parts.map(p=>p.cv?Promise.resolve(p.cv):amImgAt(p.u,p.w*kd,p.h*kd,p.w,p.h)));const W=Math.ceil((x1-x0)*k)+2*pad,H=Math.ceil((y1-y0)*k)+2*pad;
 const mk=(w,h)=>{const c=document.createElement('canvas');c.width=w;c.height=h;return c;};
 let parts;
 /* 第 190 版：所有部位共用一張畫布、照原本的位置畫（瀏覽器高品質縮圖的結果會隨位置改變，不能搬到小畫布原點畫），只讀回、處理、掃描部位佔的範圍（rmPartBox）；
    原本每個部位開一張整隻生物大小（像素版還是 4 倍大）的畫布、整張讀回兩次與掃描。範圍外本來就是透明的，減色、調色盤、網點、轉軸用的遮罩結果都和整張處理相同（qa/rig-box190-test.mjs 比對）。
    畫布用 CPU 繪製（willReadFrequently：讀回較快；原本大畫布在有顯卡的電腦上可能用顯卡畫，縮圖濾鏡有極細微的差別，像素版調色盤可能因此差一點點）。 */
 if(mode==='px'){const px=R.px;const sat=+px.sat,con=+px.con;const c=mk(W*4,H*4);const x=c.getContext('2d');x.imageSmoothingQuality='high';
  const big=lk.parts.map((p,i)=>{const b=rmPartBox(p,x0,y0,k,pad,W,H,1);const bx=b[0]*4,by=b[1]*4,bw=b[2]*4,bh=b[3]*4;x.clearRect(0,0,c.width,c.height);x.drawImage(ims[i],((p.x-x0)*k+pad)*4,((p.y-y0)*k+pad)*4,p.w*k*4,p.h*k*4);
   if(!(sat===1&&con===1)){const d0=x.getImageData(bx,by,bw,bh);rmAdjustBox(d0,sat,con,W*4,H*4,bx,by);x.putImageData(d0,bx,by);}return{b,d:x.getImageData(bx,by,bw,bh).data};});c.width=c.height=1;
  const P=rmPalette(big.map(z=>z.d),Math.max(2,Math.min(32,+px.n||10)));
  parts=lk.parts.map((p,i)=>{const c=rmPartCfg(R,p,ind);const da=new ImageData(W,H);return{p,d:rmPixelize(null,W,H,P,{dstr:+px.cdstr,clean:+px.clean,alo:c.alo,ahi:c.ahi,avg:da,sd:big[i].d,box:big[i].b}),da,box:big[i].b};});
  parts.P=P;}
 else{const c=mk(W,H);const x=c.getContext('2d',{willReadFrequently:true});x.imageSmoothingQuality='high';
  parts=lk.parts.map((p,i)=>{const b=rmPartBox(p,x0,y0,k,pad,W,H,2);x.clearRect(0,0,W,H);x.drawImage(ims[i],(p.x-x0)*k+pad,(p.y-y0)*k+pad,p.w*k,p.h*k);
   const cf=rmPartCfg(R,p,ind);const s0=x.getImageData(b[0],b[1],b[2],b[3]).data;const d=new ImageData(W,H);const a=d.data;for(let y=0;y<b[3];y++)a.set(s0.subarray(y*b[2]*4,(y+1)*b[2]*4),((b[1]+y)*W+b[0])*4);
   if(cf.alo!=null&&cf.ahi!=null){for(let q=3;q<a.length;q+=4)if(a[q]>=cf.alo&&a[q]<cf.ahi)a[q]=Math.round(a[q]*.75);}return{p,d,box:b};});c.width=c.height=1;}
 parts.forEach(t=>{const a=t.d.data;let n=0,sx=0,sy=0,bx0=W,by0=H,bx1=-1,by1=-1;const m=new Uint8Array(W*H);const B=t.box||[0,0,W,H];
  for(let y=B[1];y<B[1]+B[3];y++)for(let x=B[0];x<B[0]+B[2];x++)if(a[(y*W+x)*4+3]>40){m[y*W+x]=1;n++;sx+=x;sy+=y;if(x<bx0)bx0=x;if(x>bx1)bx1=x;if(y<by0)by0=y;if(y>by1)by1=y;}
  Object.assign(t,{m,n,cx:n?sx/n:W/2,cy:n?sy/n:H/2,bb:[bx0,by0,bx1,by1]});});
 const rig={W,H,pad,k,x0,y0,cw,parts,mode,P:parts.P,lw:lk.w,lh:lk.h,cxb:ind.__acc&&ind.__acc.length?((bx0+bx1)/2-x0)*k+pad:undefined};RM_CACHE.set(key,rig);if(RM_CACHE.size>24)RM_CACHE.delete(RM_CACHE.keys().next().value);return rig;}
/* 轉軸：和父部位接觸的地方（父部位外擴後的重疊區中心）；沒碰到就取最靠近父部位中心的點。個體可以手動指定。 */
function rmPivot(rig,t,par,ind){const o=(ind.room||{}).pv||{};const W=rig.W,H=rig.H,pad=rig.pad;
 if(Array.isArray(o[t.p.k]))return[pad+o[t.p.k][0]*(W-2*pad),pad+o[t.p.k][1]*(H-2*pad)];
 /* 第 113 版：姿勢的轉軸（姿勢畫布的比例） */const pp=typeof amPosePv==='function'?amPosePv(ind,t.p.k):null;if(pp&&rig.lw&&rig.lh)return[(pp[0]*rig.lw-rig.x0)*rig.k+pad,(pp[1]*rig.lh-rig.y0)*rig.k+pad];
 if(!par)return[t.cx,t.cy];const r=Math.max(2,Math.round(W*.015));const pm=par.m;const dil=new Uint8Array(W*H);
 for(let y=0;y<H;y++)for(let x=0;x<W;x++)if(pm[y*W+x]){for(let j=-r;j<=r;j+=r)for(let i=-r;i<=r;i+=r){const xx=x+i,yy=y+j;if(xx>=0&&yy>=0&&xx<W&&yy<H)dil[yy*W+xx]=1;}}
 let n=0,sx=0,sy=0;for(let i=0;i<W*H;i++)if(t.m[i]&&dil[i]){n++;sx+=i%W;sy+=(i/W)|0;}
 if(n>=6)return[sx/n,sy/n];let best=1e18,bp=[t.cx,t.cy];for(let i=0;i<W*H;i++)if(t.m[i]){const x=i%W,y=(i/W)|0;const d=(x-par.cx)**2+(y-par.cy)**2;if(d<best){best=d;bp=[x,y];}}return bp;}
/* ---- 動畫：每一格每個部位的變換（父子相乘）＋彎曲；像素版取最近格、原圖版雙線性 ---- */
function rmPlan(rig,ind){const R=rmCfg();const keys=rig.parts.map(t=>t.p.k);const by=new Map(rig.parts.map(t=>[t.p.k,t]));
 const rp=rmRootOf(rig.parts.map(t=>t.p).filter(p=>!p.acc));const root=rig.parts.find(t=>t.p===rp)||rig.parts[0];
 let foot=0;rig.parts.forEach(t=>{const c=rmPartCfg(R,t.p,ind);if(t===root||(R.mat[c.mat]||{}).plant)foot=Math.max(foot,t.bb[3]);});
 const plan=rig.parts.map(t=>{const c=rmPartCfg(R,t.p,ind);const pk=t===root?'':rmParentOf(t.p,keys,c,root.p.k);return{t,c,raw:typeof amPartRaw==='function'?amPartRaw(R,t.p.k,ind):null,m:R.mat[c.mat]||RM_MAT_DEF.normal,par:pk?by.get(pk)||null:null,root:t===root};});
 plan.forEach(q=>{q.pv=rmPivot(rig,q.t,q.par,ind);const t=q.t;let ux=t.cx-q.pv[0],uy=t.cy-q.pv[1];const L=Math.hypot(ux,uy)||1;ux/=L;uy/=L;
  let lm=1;for(let i=0;i<t.m.length;i++)if(t.m[i]){const d=((i%rig.W)-q.pv[0])*ux+(((i/rig.W)|0)-q.pv[1])*uy;if(d>lm)lm=d;}Object.assign(q,{ux,uy,lm});});
 /* 第 115 版：所有眼睛一起眨；每隻眼睛配自己的閉眼圖（部位設定 closed 指定，沒指定就依名稱的近／遠配對，只有一張閉眼圖時給近的或第一隻） */
 const isE=q=>{const r=q.c&&q.c.eye;return r==='eye'||(!r&&rmIsEye(q.t.p));},isC=q=>{const r=q.c&&q.c.eye;return r==='closed'||(!r&&rmIsClosed(q.t.p));};
 const eyes=plan.filter(isE),closeds=plan.filter(isC);const closedOf=new Map();const side=q=>/far|遠/.test(q.t.p.k+(q.t.p.n||''))?'f':/near|近/.test(q.t.p.k+(q.t.p.n||''))?'n':'';
 eyes.forEach(q=>{const want=q.c&&q.c.closed;if(want==='-')return;let cq=want?closeds.find(z=>z.t.p.k===want):null;if(!cq&&!want)cq=closeds.find(z=>side(z)&&side(z)===side(q));if(!cq&&!want&&closeds.length===1&&!closedOf.size){const one=closeds[0];const pick=eyes.find(e=>side(e)==='n')||eyes[0];if(pick===q&&![...closedOf.values()].includes(one))cq=one;}if(cq)closedOf.set(q,cq);});
 const eye=eyes[0]||null,closed=eye&&closedOf.get(eye)||null;
 return{plan,foot,root,eye,closed,eyes,closeds,closedOf};}

/* ---- 像素名牌字型（Unifont 的 ASCII 字形，8×16；其他字元用系統字型再二值化） ---- */
const RM_FONT='';
const rmBitW=t=>[...t].reduce((w,ch)=>{const c=ch.codePointAt(0);return w+(c>=32&&c<127?8:13);},0);
function rmBitText(x,t,X,Y,col,bg){let cx=X;x.fillStyle=`rgb(${col[0]},${col[1]},${col[2]})`;for(const ch of t){const c=ch.codePointAt(0);
 if(c>=32&&c<127){const h=RM_FONT.substr((c-32)*32,32);for(let y=0;y<16;y++){const v=parseInt(h.substr(y*2,2),16);for(let i=0;i<8;i++)if(v&(128>>i))x.fillRect(cx+i,Y+y,1,1);}cx+=8;}
 else{const tc=document.createElement('canvas');tc.width=13;tc.height=16;const tx=tc.getContext('2d');tx.font='12px sans-serif';tx.textBaseline='middle';tx.fillStyle='#fff';tx.fillText(ch,0,8);const d=tx.getImageData(0,0,13,16).data;
  for(let y=0;y<16;y++)for(let i=0;i<13;i++)if(d[(y*13+i)*4+3]>110)x.fillRect(cx+i,Y+y,1,1);cx+=13;}}}
/* ---- 房間：牆面（棲息地圖）＋地板＋兩側暗牆＋外框＋名牌＋影子＋氣泡 ---- */
const RM_WALL=new Map();

function rmPlateText(ind){const R=rmCfg();const o=ind.room||{};const t=o.plate!=null&&o.plate!==''?o.plate:R.box.plate;const no=String(ind.id).replace(/^.*-/,'');
 return String(t).replace(/\{no\}/g,no).replace(/\{id\}/g,ind.id).replace(/\{NICK\}/g,String(ind.nick||'').toUpperCase()).replace(/\{nick\}/g,ind.nick||'').replace(/\{hab\}/g,((S.habitats.find(h=>h.code===rmHabOf(ind))||{}).name)||'').trim();}
