  if(a==='tab'){RM.tab=x;RM.pick='';rmPaint();return;}
  if(a==='pick'){RM.pick=RM.pick===x?'':x;RM.tab='parts';rmPaint();return;}
  if(a==='pvclr'){if(typeof amPvClear==='function')amPvClear(ind,x);else if(ind.room&&ind.room.pv)delete ind.room.pv[x];save();rmRender();if(UI.tab==='studio')renderStudio();return;}
  if(a==='matnew'){const R=rmCfg();let k='m'+(Object.keys(R.mat).length+1);while(R.mat[k])k+='x';R.mat[k]={n:'新材質',rot:3,lag:.1,bend:.03,puff:.01,waves:.6};save();rmPaint();return;}
  if(a==='matreset'){if(!rmTwo('rmmat')){toast('再按一次還原所有材質的預設值');return;}const R=rmCfg();R.mat={};rmCfg();save();rmPaint();rmSoon();return;}
  if(a==='wallrm'){const R=rmCfg();const w=R.hab[x]&&R.hab[x].img;delete R.hab[x];if(w&&typeof dropAsset==='function')dropAsset(w);save();rmPaint();rmSoon();return;}
  if(a==='gif'||a==='apng'){if(!RM.fr||RM.busy)return;(async()=>{try{toast('輸出中…',3000);const nm=`${ind.id}${ind.nick?'_'+ind.nick:''}_${RM.mode==='px'?'pixel':'original'}`;
   if(a==='gif')await dlSave(nm+'.gif',await rmGif(RM.fr,RM.mode==='px'?+x||1:1));else await dlSave(nm+'.png',await rmApng(RM.fr));}catch(er){toast('輸出失敗：'+((er&&er.message)||er),6000);}})();return;}
