  if(c.tw){const at=Math.round(twAt(c.tw.at)*L)%L,len=Math.max(1,Math.round((+c.tw.len||1)*tws));const k=(i-at+L)%L;
   if(k<len){const u=(k+.5)/len,e=len>=L?1:(t=>t*t*(3-2*t))(Math.min(1,Math.min(u,1-u)/.3));ang+=(+c.tw.ang||0)*e;}}
