 const {world,blink}=rmFrameMats(rig,P,i,L);const S1=(q,m)=>{const c=q.c||{};const amp=q.root?1:(c.amp==null?1:+c.amp);const lag=(+m.lag||0)+(+c.lag||0);return{amp,lag,s:Math.sin(TAU*(t-lag))};};
