  const m=amMatOf(q,R),c=q.c||{};const {amp,lag,s}=S1(q,m);const base=world.get(q.t);const bb=q.t.bb;if(!base||bb[2]<0)return;
  /* 第 126 版：P.avg＝用還沒打網點的平均色（像素版的生物立體網格） */const src=q.t.frames&&q.t.frames.length?q.t.frames[Math.floor(t*q.t.frames.length)%q.t.frames.length]:P.avg&&q.t.da?q.t.da:q.t.d;const sd=src.data;
