const AM_SURF_KIND={wall:'缸壁',water:'水面'};
const AM_SURF_TYPES={
 wall:{
  glass:{n:'玻璃（側面倒影）',d:'側面的玻璃像鏡子一樣映出缸內的景象，每樣東西以它所在深度的側牆為鏡面翻轉。',p:{refl:[.62,0,1,.02,'倒影強度'],tint:[.22,0,1,.02,'玻璃色']}},
  plain:{n:'不反光',d:'側牆不映出倒影，只有厚度與邊緣線。',p:{}}},
 water:{
  calm:{n:'水面（倒影、水面線、波紋）',d:'視線在水面以下時，水面的下側像鏡子映出缸內的景象（越靠近水面的東西映得越清楚）；視線在水面以上時，看到的是水面的反光，越往後越亮。正面玻璃上有一條水面線，波紋讓倒影輕輕晃動。',
   p:{level:[.88,.3,1,.01,'水位（缸高的比例）'],refl:[.6,0,1,.02,'倒影強度'],line:[.85,0,1,.05,'水面線亮度'],wave:[.4,0,1,.05,'波紋'],tintA:[0,0,.5,.02,'水色濃度']},col:{tint:['#3a7bd5','水色']}}}};
const AM_SURF_BUILTIN=[{id:'glass',kind:'wall',type:'glass',n:'玻璃（預設）',builtin:1},{id:'plain',kind:'wall',type:'plain',n:'不反光的牆',builtin:1},{id:'water',kind:'water',type:'calm',n:'水面',builtin:1}];
function amSurfs(){var f=ghRestGet("amSurfs");return new.target?Reflect.construct(f,arguments):f.apply(this,arguments);}amSurfs.__rs=1;
function amSurfAll(){var f=ghRestGet("amSurfAll");return new.target?Reflect.construct(f,arguments):f.apply(this,arguments);}amSurfAll.__rs=1;
function amSurfGet(id){return id?AM_SURF_BUILTIN.find(s=>s.id===id)||amSurfs().find(s=>s.id===id)||null:null;}
function amSurfType(s){return s&&AM_SURF_TYPES[s.kind]&&AM_SURF_TYPES[s.kind][s.type]||null;}
