const AM_SWAY_C=[.25,1/3,.5,1,2,3,4];
const amV3Box=code=>{const B=amBox(code);const c=(v,d,a,b)=>Math.max(a,Math.min(b,amNum(v,d)));const sc=c(B.swayC,1,.25,4);return{yaw:c(B.yaw,0,-40,40),kst:c(B.kst,.5,0,1),swayA:c(B.swayA,0,0,20),swayC:AM_SWAY_C.reduce((a,b)=>Math.abs(b-sc)<Math.abs(a-sc)?b:a),/* 第 147 版：轉動中心（''＝自動、c＝生物身體、t＝缸體中間） */orb:B.orb==='c'||B.orb==='t'?B.orb:''};};
/* 預設視角的俯角（這以內不傾斜） */
