  const sh=(t,src)=>{const s=gl.createShader(t);gl.shaderSource(s,src);gl.compileShader(s);return s;};const pr=gl.createProgram();
  gl.attachShader(pr,sh(gl.VERTEX_SHADER,'attribute vec4 aP;attribute vec3 aT;varying vec3 vT;void main(){vT=aT;gl_Position=aP;}'));
