const MR_ALLOW=[['tpl','風格','套用你公開的房間模板'],/* 第 151 版：視角改成拖曳轉動、擺動改成開關＋拉桿 */['view','轉動視角','在棲息地與養殖艙拖曳轉動（不超過全站上限）'],['sway','左右搖擺','開關搖擺、調整幅度與速度'],['pos','移動生物','左右、前後、在預覽上拖曳'],['wear','取下飾品','取下或恢復綁定的飾品'],/* 第 117 版 */['out','輸出工作室','把房間放進你的海報風格排版，輸出會動的 GIF']];
const mrAllowOf=o=>{const a=(o&&o.allow)||{};const r={};MR_ALLOW.forEach(([k])=>{r[k]=a[k]===0?0:1;});return r;};
