/* ---- 畫房間用的物種：飼主鑰匙裡的小房間設定＋目前選的模板、視角卡、擺動卡 ---- */
function mrSpecies(o){/* 第 163 版：未持有的棲息地用公開的資料 */const r=mrRoomAll();const room={...clone(r.set||{}),hab:{},tpls:[],gal:{}};Object.entries(r.habs||{}).forEach(([c,o])=>{room.hab[c]=clone(o.cfg||{});});
 const hc=room.hab[MR.hab]=room.hab[MR.hab]||{};const box=hc.box=hc.box&&typeof hc.box==='object'?hc.box:{};/* 第 151 版：o.noTpl＝不套用模板（養殖艙的模板只在「養殖艙」分頁套用） */const t=mrCan('tpl')&&!(o&&o.noTpl)?(r.tpls||[]).find(x=>x.id===MR.tpl):null;
 if(t&&t.v){MR_TPL_KEYS().forEach(k=>{if(t.v[k]!=null&&t.v[k]!=='')box[k]=+t.v[k];});if('cs' in t.v){if(t.v.cs!=null&&+t.v.cs!==1)hc.cs=+t.v.cs;else delete hc.cs;}
  /* 第 180 版：模板只存了缸壁或水面其中一個時，另一個照棲息地 */if(t.v.surf){const sf={...(hc.surf||{})};if('wall' in t.v.surf){if(t.v.surf.wall&&t.v.surf.wall!=='glass')sf.wall=t.v.surf.wall;else delete sf.wall;}if('water' in t.v.surf){if(t.v.surf.water)sf.water=t.v.surf.water;else delete sf.water;}if(Object.keys(sf).length)hc.surf=sf;else delete hc.surf;}}
 if(t&&t.v)amTplScene(hc,t.v);
 const v=mrView(),w=mrSway();/* 第 116 版：卡片關掉時照模板（沒有模板就照棲息地） */if(mrCan('view'))box.yaw=+v.yaw||0;else if(t&&t.v&&t.v.yaw!=null)box.yaw=+t.v.yaw||0;
 /* 第 119 版：套用風格（模板）時，擺動幅度與速度照模板（擺動卡只用在沒有選風格的時候） */
 if(t&&t.v&&(t.v.swayA!=null||t.v.swayC!=null)){if(t.v.swayA!=null)box.swayA=+t.v.swayA||0;if(t.v.swayC!=null)box.swayC=+t.v.swayC||1;}else if(mrCan('sway')){box.swayA=+w.a||0;box.swayC=+w.c||1;}
 const paper=(PUB.sp&&PUB.sp.paper)||{};const parts=(paper.parts||[]).map(x=>({id:'pt_'+x.k,key:x.k,n:x.n,al:x.al||[]}));
 return{...S,room,habitats:Object.entries(r.habs||{}).map(([code,o])=>({code,name:o.name,en:o.en||''})),looks:{poses:[],def:{},parts,migrated:1},inds:[]};}
let MR_LOCK=Promise.resolve();
/* 一次只畫一間：畫的時候把 S（與訪客端的材質庫）換成飼主的小房間資料，畫完換回來 */
/* 第 151 版：切換拆成 mrEnter（回傳換回來的函式），養殖艙拖曳視角時同步使用 */
function mrEnter(o){const keepS=S,keepA=STORE.anim;S=mrSpecies(o);if(!rmOwner()){const r=mrRoomAll();const fl=(r&&r.floors)||[];const fid=new Set(fl.map(f=>f.id));STORE.anim={...(keepA||{}),mat:{...((keepA&&keepA.mat)||{}),...((r&&r.mat)||{})},floors:[...(((keepA&&keepA.floors)||[]).filter(f=>!fid.has(f.id))),...fl],fx:[...(((keepA&&keepA.fx)||[]).filter(f=>!((r&&r.fx)||[]).some(z=>z.id===f.id))),...((r&&r.fx)||[])]};}
 return()=>{S=keepS;STORE.anim=keepA;};}
function mrWith(fn,o){const run=MR_LOCK.then(async()=>{const back=mrEnter(o);
  try{return await fn();}finally{back();}});MR_LOCK=run.catch(()=>{});return run;}
