  const out=t.parentNode&&t.parentNode.querySelector('.amsl-v');if(out)out.textContent=k==='psw'?(/^c/.test(i)?amSwayCName(AM_SWAY_C[+t.value]||1):`${Math.round(+t.value||0)}°`):k==='lim'?(i==='yaw'?`±${Math.round(+t.value||0)}°`:`±${(+t.value||0).toFixed(2)}`):k==='view'||k==='swa'?`${Math.round(+t.value||0)}°`:k==='swc'?amSwayCName(AM_SWAY_C[+t.value]||1):'';
