 document.addEventListener('wheel',e=>{if(UI.tab!=='studio'||!e.target||!e.target.closest||!e.target.closest('#tab-studio .rm-cvw'))return;e.preventDefault();e.stopPropagation();const cv=document.getElementById('rm-cv');if(!cv)return;
  if(e.ctrlKey||e.metaKey){const z0=STU.zoom||1;const f=Math.exp(-Math.max(-60,Math.min(60,e.deltaY))*.01);amStuZoomTo(Math.max(.5,Math.min(8,+(z0*f).toFixed(3))),e.clientX,e.clientY);return;}
  const p=STU.pan||[0,0];STU.pan=[p[0]-e.deltaX,p[1]-e.deltaY];amPanApply(cv);},{passive:false,capture:true});
 /* 空白鍵 */
 window.addEventListener('keydown',e=>{if(e.code!=='Space'||UI.tab!=='studio'||amIsTyping(e.target))return;e.preventDefault();if(e.target&&e.target.tagName==='BUTTON'&&e.target.blur)e.target.blur();if(!STU.space){STU.space=true;const w=amStuWrap();if(w)w.classList.add('c3space');}},true);
 const spUp=()=>{if(!STU.space)return;STU.space=false;const w=amStuWrap();if(w)w.classList.remove('c3space');};window.addEventListener('keyup',e=>{if(e.code==='Space')spUp();},true);window.addEventListener('blur',spUp);
 /* 觸控兩指：移動＋縮放 */
 const T=new Map();const two=()=>{const [a,b]=[...T.values()];return{cx:(a.x+b.x)/2,cy:(a.y+b.y)/2,d:Math.hypot(a.x-b.x,a.y-b.y)};};
 window.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch'||UI.tab!=='studio'||!e.target.closest||!e.target.closest('#tab-studio .rm-cvw'))return;T.set(e.pointerId,{x:e.clientX,y:e.clientY});if(T.size===2){STU.drag=null;const m=two();STU.pinch={...m,z0:STU.zoom||1,p0:(STU.pan||[0,0]).slice()};e.stopImmediatePropagation();}},true);
 window.addEventListener('pointermove',e=>{if(!T.has(e.pointerId))return;T.set(e.pointerId,{x:e.clientX,y:e.clientY});const P=STU.pinch;if(!P||T.size<2)return;e.stopImmediatePropagation();const m=two();const cv=document.getElementById('rm-cv');STU.pan=[P.p0[0]+m.cx-P.cx,P.p0[1]+m.cy-P.cy];amPanApply(cv);const z=Math.max(.5,Math.min(8,+(P.z0*m.d/(P.d||1)).toFixed(3)));amStuZoomTo(z,m.cx,m.cy);},true);
