  if(d.matches('details.step')){UI.steps=UI.steps||{};UI.steps[d.dataset.step]=d.open;if(d.open&&/^art/.test(d.dataset.step||''))artPrevFill(d.dataset.step==='art'?'ind':'cat:'+d.dataset.step.slice(4));return;}
